import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// The tuner's logic (detection, smoothing, note mapping, layout math), shared by two front ends:
// - jvm: used by the Android app (:app).
// - js: compiled to an ES module with TypeScript types and copied into the website (task exportToSite).
plugins {
    kotlin("multiplatform")
}

// The Node.js repository is declared in settings.gradle.kts; stop the plugin from adding its own.
listOf(project, rootProject).forEach { p ->
    p.plugins.withType<org.jetbrains.kotlin.gradle.targets.js.nodejs.NodeJsPlugin> {
        p.the<org.jetbrains.kotlin.gradle.targets.js.nodejs.NodeJsEnvSpec>().downloadBaseUrl.set(null as String?)
    }
}

// The ear and voice training tables stay as JSON in the website (the owner edits them there): src/tools/treino-de-ouvido/dados.json
// and musicas.json. This task writes the same data as Kotlin into build/generated/treino, which joins commonMain. No JSON library
// in the app: JsonSlurper ships with Gradle.
val treinoDir = rootDir.resolve("../src/tools/treino-de-ouvido")
val generateTreinoData = tasks.register("generateTreinoData") {
    description = "Writes TreinoDados.kt from the website's dados.json and musicas.json."
    val dados = treinoDir.resolve("dados.json")
    val musicas = treinoDir.resolve("musicas.json")
    val out = layout.buildDirectory.dir("generated/treino")
    inputs.files(dados, musicas)
    outputs.dir(out)
    doLast {
        val slurper = groovy.json.JsonSlurper()
        @Suppress("UNCHECKED_CAST") val d = slurper.parse(dados) as Map<String, Any?>
        @Suppress("UNCHECKED_CAST") val ms = slurper.parse(musicas) as List<Map<String, Any?>>
        fun str(v: Any?) = "\"" + v.toString().replace("\\", "\\\\").replace("\"", "\\\"").replace("$", "\\$") + "\""
        fun int(v: Any?) = (v as Number).toInt().toString()
        fun dbl(v: Any?) = (v as Number).toDouble().toString()
        fun ints(v: Any?) = (v as List<*>).joinToString(", ", "arrayOf(", ")") { int(it) }
        fun strs(v: Any?) = (v as List<*>).joinToString(", ", "arrayOf(", ")") { str(it) }
        @Suppress("UNCHECKED_CAST") fun lista(k: String) = d[k] as List<Map<String, Any?>>
        fun tabela(nome: String, tipo: String, linhas: List<String>) =
            "val $nome: Array<$tipo> = arrayOf(\n" + linhas.joinToString(",\n") { "    $it" } + ",\n)\n"
        @Suppress("UNCHECKED_CAST") val cad = (d["cadencia"] as Map<String, Any?>)["acordes"] as List<Map<String, Any?>>
        val sb = StringBuilder()
        sb.append("// GENERATED by :core:generateTreinoData from src/tools/treino-de-ouvido/dados.json and musicas.json. Do not edit.\n")
        sb.append("@file:OptIn(kotlin.js.ExperimentalJsExport::class)\n@file:kotlin.js.JsExport\n\npackage br.musica.marmotatuner.treino\n\n")
        sb.append(tabela("INTERVALOS", "Intervalo", lista("intervalos").map { "Intervalo(${str(it["id"])}, ${int(it["semitons"])})" }))
        sb.append(tabela("ACORDES", "Acorde", lista("acordes").map { "Acorde(${str(it["id"])}, ${ints(it["semitons"])})" }))
        sb.append(tabela("GRAUS", "Grau", lista("graus").map { "Grau(${str(it["id"])}, ${int(it["semitons"])})" }))
        sb.append(tabela("CADENCIA", "AcordeDaCadencia", cad.map { "AcordeDaCadencia(${int(it["grau"])}, ${ints(it["semitons"])})" }))
        sb.append(tabela("CAMPO", "GrauDoCampo", lista("campo").map { "GrauDoCampo(${str(it["id"])}, ${int(it["raiz"])}, ${ints(it["semitons"])})" }))
        sb.append(tabela("CADENCIAS", "Cadencia", lista("cadencias").map { c ->
            "Cadencia(${str(c["id"])}, ${(c["variantes"] as List<*>).joinToString(", ", "arrayOf(", ")") { strs(it) }})"
        }))
        sb.append(tabela("PROGRESSOES", "Progressao", lista("progressoes").map { "Progressao(${str(it["id"])}, ${strs(it["acordes"])})" }))
        sb.append(tabela("PADROES", "Padrao", lista("padroes").map { "Padrao(${str(it["id"])}, ${ints(it["semitons"])})" }))
        sb.append(tabela("MUSICAS", "Musica", ms.map { m ->
            @Suppress("UNCHECKED_CAST") val trechos = (m["trechos"] as List<Map<String, Any?>>).joinToString(",\n        ", "arrayOf(\n        ", ",\n    )") { t ->
                @Suppress("UNCHECKED_CAST") val notas = (t["notas"] as List<Map<String, Any?>>).joinToString(", ") { n ->
                    "n(${n["st"]?.let { int(it) } ?: "null"}, ${dbl(n["dur"])}, ${str(n["sil"])})"
                }
                "Trecho(${str(t["nome"])}, arrayOf($notas))"
            }
            "Musica(${str(m["id"])}, ${str(m["nome"])}, ${str(m["compasso"])}, ${int(m["bpm"])}, ${str(m["confianca"])}, $trechos)"
        }))
        sb.append("\nprivate fun n(st: Int?, dur: Double, sil: String) = NotaMusica(st, dur, sil)\n")
        val f = out.get().asFile.resolve("br/musica/marmotatuner/treino/TreinoDados.kt")
        f.parentFile.mkdirs()
        f.writeText(sb.toString())
    }
}

kotlin {
    jvm {
        compilerOptions { jvmTarget.set(JvmTarget.JVM_17) }
    }
    js(IR) {
        outputModuleName = "tuner-core"
        browser { testTask { enabled = false } }
        binaries.library()
        generateTypeScriptDefinitions()
        useEsModules()
    }
    sourceSets {
        commonMain { kotlin.srcDir(generateTreinoData) }
        jvmTest.dependencies {
            implementation("junit:junit:4.13.2")
            // Tests only: reads the parity fixtures written by the website (treino-fixtures.json).
            implementation("org.json:json:20250517")
        }
    }
}

// The website can't run Gradle (Vercel has no JDK), so the compiled JS is committed to the site.
// Run after changing anything in core/src/commonMain: ./gradlew :core:exportToSite
val siteDir = rootDir.resolve("../src/core/pitch/generated")
tasks.register<Sync>("exportToSite") {
    description = "Copies the compiled JS + .d.mts into the website (src/core/pitch/generated)."
    from(tasks.named("jsBrowserProductionLibraryDistribution"))
    include("*.mjs", "*.d.ts")
    // TypeScript pairs foo.mjs with foo.d.mts, not foo.d.ts.
    rename("""(.*)\.d\.ts""", "$1.d.mts")
    // The .map files are not copied, so drop the comments that point to them (Vite warns about missing maps).
    filesMatching("*.mjs") { filter { line -> if (line.startsWith("//# sourceMappingURL=")) "" else line } }
    into(siteDir)
}
